<?php $page_title='Mata Kuliah Saya';require_once __DIR__.'/../includes/header.php';require_login(['dosen']);$q=db()->prepare('SELECT kl.nama_kelas,m.kode,m.nama,m.sks,t.tahun,t.semester FROM kelas kl JOIN mata_kuliah m ON m.id=kl.id_mk JOIN tahun_akademik t ON t.id=kl.id_tahun_akademik WHERE kl.id_dosen=?');$q->execute([lecturer_id()]);$rows=$q->fetchAll();?><h3 class="mb-4">Mata Kuliah yang Diajar</h3><div class="card p-4"><table class="table datatable"><thead><tr><th>Kode</th><th>Mata Kuliah</th><th>Kelas</th><th>SKS</th><th>Periode</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['kode'])?></td><td><?=e($r['nama'])?></td><td><?=e($r['nama_kelas'])?></td><td><?=$r['sks']?></td><td><?=e($r['tahun'].' '.$r['semester'])?></td></tr><?php endforeach?></tbody></table></div><?php require_once __DIR__.'/../includes/footer.php';?>
